from pathlib import Path
p=Path('lib/music.ts');s=p.read_text();s=s[s.index('export const frequency'):];s=s[:s.index('const chords:')];p.write_text("import { parseScore, type Tempo } from './score.ts';\nimport { builtinScores } from './builtin-scores.ts';\nexport type Note = { midi: number; start: number; duration: number; hand: 'left' | 'right' };\nexport type Song = { id: string; title: string; subtitle: string; bpm: number; notes: Note[]; duration: number; xml: string; tempos: Tempo[] };\nexport const songs: Song[] = builtinScores.map(({id,xml})=>parseScore(xml,id));\n"+s)
p=Path('lib/score.ts');s=p.read_text().replace("import { DOMParser }", "import { DOMParser, type Element }").replace('root as unknown as Element','root');p.write_text(s)
p=Path('components/Scene.tsx');s=p.read_text().replace('lightweight:boolean;','').replace('shadows={!props.lightweight} dpr={props.lightweight?1:[1,1.75]}','shadows dpr={[1,1.75]}').replace('{!props.lightweight&&<ContactShadows','<ContactShadows').replace('resolution={512}/>}','resolution={512}/>');p.write_text(s)
